    // Add padding to sB to avoid bank conflicts if TILE_SIZE is a multiple of warp size (32)
    // For TILE_SIZE=32, sB[k][threadIdx.x] might cause bank conflicts if threadIdx.x is used as column index
    // A common way to avoid this is to pad the shared memory array
    __shared__ float sA[TILE_SIZE][TILE_SIZE];
    __shared__ float sB[TILE_SIZE][TILE_SIZE + 1]; // +1 for padding

    float sum = 0.0f; // Accumulator in register

    // Iterate over tiles
    int numTiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int t = 0; t < numTiles; ++t) {
        // Load tiles into shared memory
        // Coalesced access for A: threads in a warp access contiguous memory locations
        int globalRowA = blockRow * TILE_SIZE + threadIdx.y;
        int globalColA = t * TILE_SIZE + threadIdx.x;
        if (globalRowA < N && globalColA < N) {
            sA[threadIdx.y][threadIdx.x] = A[globalRowA * N + globalColA];
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if out of bounds
        }

